I have verified that this is entirely due to weakref_lru_cache when used to make an object jaxpr to a wrapper for jaxpr:
  def test_weakref_lru_cache_with_wrappers(self):

    class MyClass:
      def __init__(self, x):
        self.x = x

    class MyWrapperClass:
      def __init__(self, c:  MyClass):
        self.c = c

    @util.weakref_lru_cache
    def memoize(c: MyClass) -> MyWrapperClass:
      return MyWrapperClass(c)

    c0 = MyClass(0)
    w0_1 = memoize(c0)
    w0_2 = memoize(c0)
    self.assertIs(w0_1, w0_2)
    keys_1 = memoize.cache_keys()
    self.assertLen(keys_1, 1)

    del c0, w0_1, w0_2
    keys_0 = memoize.cache_keys()
    self.assertEmpty(keys_1)  # Fails, keys_1 has one entry

