class T2Array:
    """
    Arithmetic for [x + v ε + u/2 ε^2]:
    f(x + v ε + u/2 ε^2) = f(x) + ∂f(x)[v] ε + 1/2 * (∂f(x)[u] + ∂^2f(x)[v,v]) ε^2
