    def __init__(self, x: np.ndarray | jnp.ndarray, v: np.ndarray | jnp.ndarray | None = None, u: np.ndarray | jnp.ndarray | None = None):
        self.x = x
        self.v = v if v is not None else jnp.zeros_like(x)
        self.u = u if u is not None else jnp.zeros_like(x)
        assert(self.x.shape == self.v.shape == self.u.shape)
        self.shape = x.shape
        self.size = x.size

    def __repr__(self):
        return {'x':self.x, 'v':self.v, 'u':self.u}.__repr__()

    # Array operations
    def __getitem__(self, key) -> Self:
        return T2Array(self.x.__getitem__(key), self.v.__getitem__(key), self.u.__getitem__(key))

    def __setitem__(self, key, value) -> None:
        """
        Immutable array
        """
        return None

    def __len__(self):
        return self.x.__len__()

    # Uniary arithmetic
    def __neg__(self) -> Self:
        return T2Array(self.x.__neg__(), self.v.__neg__(), self.u.__neg__())

    def __pos__(self) -> Self:
        return T2Array(self.x.__pos__(), self.v.__pos__(), self.u.__pos__())

    def inv(self) -> Self:
        return T2Array(1/self.x, -self.v/self.x**2, 2*self.v**2/self.x**3-self.u/self.x**2)

    # TODO Fast implementation
    def matinv(self) -> Self:
        invx = jnp.linalg.inv(self.x)
        invv = invx@self.v@invx
        return T2Array(invx, -invv, 2*invv@self.v@invx - invx@self.u@invx)

    def sin(self) -> Self:
        sin, cos = jnp.sin(self.x), jnp.cos(self.x)
        return T2Array(sin, cos * self.v, cos * self.u - sin * self.v * self.v)

    def cos(self) -> Self:
        sin, cos = jnp.sin(self.x), jnp.cos(self.x)
        return T2Array(cos, -sin * self.v, -sin * self.u - cos * self.v * self.v)

    def sincos(self) -> Self:
        sin, cos = jnp.sin(self.x), jnp.cos(self.x)
        return T2Array(sin, cos * self.v, cos * self.u - sin * self.v ** 2), T2Array(cos, -sin * self.v, -sin * self.u - cos * self.v ** 2)

    def exp(self) -> Self:
        exp = jnp.exp(self.x)
        return T2Array(exp, exp * self.v, exp * (self.u + self.v ** 2))

    def log(self) -> Self:
        log = jnp.log(self.x)
        return T2Array(log, self.v/self.x, self.u/self.x - self.v ** 2 / self.x ** 2)

    # Binary arithmetic
    def __add__(self, other: Number | np.ndarray | jnp.ndarray | Self):
        if isinstance(other, (Number, np.ndarray, jnp.ndarray)):
            return T2Array(self.x.__add__(other), self.v, self.u)
        elif isinstance(other, T2Array):
            return T2Array(self.x.__add__(other.x), self.v.__add__(other.v), self.u.__add__(other.u))
        raise TypeError(f'Invalid input type {type(other)}, expected Number | jnp.ndarray | T2Array')

    def __sub__(self, other: Number | np.ndarray | jnp.ndarray | Self):
        if isinstance(other, (Number, np.ndarray, jnp.ndarray)):
            return T2Array(self.x.__sub__(other), self.v, self.u)
        elif isinstance(other, T2Array):
            return T2Array(self.x.__sub__(other.x), self.v.__sub__(other.v), self.u.__sub__(other.u))
        raise TypeError(f'Invalid input type {type(other)}, expected Number | jnp.ndarray | T2Array')

    def __mul__(self, other: Number | np.ndarray | jnp.ndarray | Self):
