            return T2Array(self.x.__mul__(other), self.v.__mul__(other), self.u.__mul__(other))
        elif isinstance(other, T2Array):
            return T2Array(self.x.__mul__(other.x), self.x.__mul__(other.v) + self.v.__mul__(other.x), self.x.__mul__(other.u) + self.u.__mul__(other.x) + self.v.__mul__(other.v) * 2)
        raise TypeError(f'Invalid input type {type(other)}, expected Number | jnp.ndarray | T2Array')

    def __matmul__(self, other: np.ndarray | jnp.ndarray | Self):
        if isinstance(other, (np.ndarray, jnp.ndarray)):
            return T2Array(self.x.__matmul__(other), self.v.__matmul__(other), self.u.__matmul__(other))
        elif isinstance(other, T2Array):
