  def f1():
    print("callback:")
    print(f" {x+y=}")
    print(f" {2*x-y+np.pi=}")
    print(f" {[z, z-x]=}")

  @debug_closure(ordered=True)
  def f2():
    print(f"callback(ordered): {out=}")

  return out

