conversation.output:
Thanks for the tag! So @crusaderky you can probably work around JAX's lack of support for runtime errors in the exact same way that Equinox does: wrap both the callback and the JIT, and smuggle the exception between the two using global state.
It's ugly, but it works! (We do the exact same thing between eqx.filter_jit and eqx.error_if to support pretty readable runtime error messages.)
Here's a quick demo:
import functools as ft
import logging
import weakref

import jax


_better_fs = weakref.WeakKeyDictionary()
_last_e = None


class _FilterCallback(logging.Filterer):
    def filter(self, record: logging.LogRecord):
        return not (
            record.name == "jax._src.callback"
            and record.getMessage() == "jax.pure_callback failed"
        )


@ft.wraps(jax.pure_callback)
def better_pure_callback(f, *args, **kwargs):
    try:
        better_f_impl = _better_fs[f]
    except KeyError:

        def better_f_impl(*args, **kwargs):
            global _last_e
            try:
                return f(*args, **kwargs)
            except Exception as e:
                assert _last_e is None
                _last_e = e
                raise

        _better_fs[f] = better_f_impl
    return jax.pure_callback(better_f_impl, *args, **kwargs)


def _strip_frame(module_name: str) -> bool:
    return module_name.startswith("jax._src") or module_name == __name__


@ft.wraps(jax.jit)
def better_jit(f):
    jit_f = jax.jit(f)

    def better_jit_impl(*args, **kwargs):
        global _last_e
        filter = _FilterCallback()
        callback_logger = logging.getLogger("jax._src.callback")
        callback_logger.addFilter(filter)
        try:
            out = jit_f(*args, **kwargs)
            return out
        except jax.errors.JaxRuntimeError as e:
            if _last_e is None:
                # Something else went wrong, go back to default JAX behaviour.
                to_raise = e
            else:
                to_raise = _last_e
                _last_e = None
        finally:
            callback_logger.removeFilter(filter)
        # Now raise outside the `except` block so we don't adjust any `__context__`.
        # We do this in a 'pointless' try-except just so that we can strip the current
        # frame from the traceback.
        try:
            raise to_raise
        except Exception as e:
            tb = e.__traceback__
            while tb is not None and _strip_frame(
                tb.tb_frame.f_globals.get("__name__", "")
            ):
                tb = tb.tb_next
            e.__traceback__ = tb
            raise

    return better_jit_impl
Try it out:
