Okay, well in this case I my solution is to add a skip_post_init flag. The post_init is only necessary at initial creation time, not for flattening.
@dataclasses.dataclass
class Pytree:
    x: jax.Array
    values: jax.Array
    axis: int
    skip_post_init: bool = False

    def __post_init__(self):
        if skip_post_init:
            return
        assert np.shape(self.values)[self.axis] == np.size(self.x)


def pytree_flatten(p: Pytree):
    return (
        [p.x, p.values],
        (p.axis,)
    )


def pytree_unflatten(aux_data, children):
    x, values = children
    axis, = aux_data
    return Pytree(x, values, axis, skip_post_init=True)


jax.tree_util.register_pytree_node(
    Pytree,
    pytree_flatten,
    pytree_unflatten
)

