That was indeed the problem! The modified example works for all strategies where the minor-most axis is reduced:
def sum_kernel(x_ref, o_ref, last_axis):
    @pl.when(pl.program_id(axis=last_axis) == 0)
    def _():
        o_ref[...] = jnp.zeros_like(o_ref)
    o_ref[...] += x_ref[...]

@functools.partial(jax.jit, static_argnames=["b1", "b2", "strategy", "interpret"])
def sum_fn(x: jax.Array, b1: int, b2: int, strategy: str, interpret: bool = False) -> jax.Array:
    g0, *out_shape = x.shape  # grid is the first dimension of x
    g1 = out_shape[0] // b1
    g2 = out_shape[1] // b2
    print(f"g0: {g0}, g1: {g1}, g2: {g2}")

    if strategy == "user_major_dimension":
        grid = (g0, g1, g2)
        in_specs = [pl.BlockSpec(block_shape=(None, b1, b2), index_map=lambda i, j, k: (i, j, k))]
        out_specs = pl.BlockSpec(block_shape=(b1, b2), index_map=lambda i, j, k: (j, k))
    elif strategy == "1d_minor_dimension":
        grid = (g0,)
        in_specs = [pl.BlockSpec(block_shape=(None, *out_shape), index_map=lambda k: (k, 0, 0))]
        out_specs = pl.BlockSpec(block_shape=tuple(out_shape), index_map=lambda k: (0, 0))
    else:
      grid = (g1, g2, g0)
      in_specs = [pl.BlockSpec(block_shape=(None, b1, b2), index_map=lambda i, j, k: (k, i, j))]
      out_specs = pl.BlockSpec(block_shape=(b1, b2), index_map=lambda i, j, k: (i, j))
      if strategy == "faux_3d_minor_dimension":
        assert g1 == g2 == 1, "In faux 3d minor dimension reduction, dimensions g1, g2 must == 1"
      elif strategy == "full_3d_minor_dimension":
        pass
      else:
        raise ValueError(f"{strategy = } not supported.")

    return pl.pallas_call(
        functools.partial(sum_kernel, last_axis=len(grid) - 1),
        grid=grid,
        in_specs=in_specs,
        out_specs=out_specs,
        out_shape=jax.ShapeDtypeStruct(out_shape, x.dtype),
        interpret=interpret,
    )(x)

It’s true that “non differentiable argument” need not imply “static argument”. But this feature is actually for declaring static arguments, and the name was chosen badly.
We should probably:

Change the name to static_argnums (except keep the old one working for back compatibility);
add the check to custom_jvp;
add a new convenience feature for array like (ie tracery) values that we don’t want involved in differentiation.

The third has limited upside because you can already get this behavior today by passing in ordinary arguments and just ignoring their corresponding tangents.

