import jax
import jax.numpy as jnp


def fun(x):
  x1 = x * 2
  y1 = x1.at[:-1, ...].set(jnp.logical_and(x1[:-1, ...], x1[1:, ...]))
  z1 = x1.at[:, :-1, ...].set(jnp.logical_and(x1[:, :-1, ...], x1[:, 1:, ...]))
  return x1, y1, z1

shape = (3, 3)
key = jax.random.key(0)
x = (jax.random.uniform(key, shape) < 0.5).astype("int32")

hlo_cpu = jax.jit(fun, backend="cpu").lower(x).as_text()
hlo_gpu = jax.jit(fun, backend="cuda").lower(x).as_text()
assert hlo_cpu == hlo_gpu

r_cpu = jax.jit(fun, backend="cpu")(x)
r_gpu = jax.device_get(jax.jit(fun, backend="cuda")(x))

assert jnp.all(r_cpu[0] == r_gpu[0])
