import jax
import jax.numpy as jnp
from jax.sharding import Mesh, PartitionSpec as P
from jax.experimental.shard_map import shard_map
from functools import partial

def collective_max(x, axis=None, keepdims=False):
    mesh = Mesh(jax.devices(), axis_names=('i'))

    @partial(shard_map, mesh=mesh, in_specs=(P('i')), out_specs=P(None))
    def _collective_max(x):
        tmp1 = jnp.max(x, axis=axis, keepdims=keepdims)
        tmp2 = tmp1[None]
        tmp3 = jax.lax.all_gather(tmp2, 'i', tiled=True)
        return jnp.max(tmp3, axis=0)

    return _collective_max(x)

