import jax.numpy as jnp
import chex
import numpy as np

chex.set_n_cpu_devices(4)

def roll_existing(x):
  return jnp.roll(x, +1)

def roll_concat(x):
  return jnp.concatenate([x[-1:], x[:-1]])

def roll_gather(x):
  indices = np.concatenate([[x.size - 1], np.arange(x.size - 1)])
  return x.at[indices].get(unique_indices=True)

